        not isinstance(name, str)
        or not isinstance(versions, list)
        or any(type(version) is not int for version in versions)
        for name, versions in blocked.items()
    ):
        return {"error": "unsatisfiable"}
    if any(
        not isinstance(name, str) or type(version) is not int
        for name, version in pins.items()
    ):
        return {"error": "unsatisfiable"}

    names = sorted(packages)
    initial_bounds = {}
    for name, interval in roots.items():
        if not valid_interval(interval):
            return {"error": "unsatisfiable"}
        initial_bounds[name] = tuple(interval)

    best_vector = None
    best_versions = None

    def search(selected, required, bounds, graph):
        nonlocal best_vector, best_versions
        pending = sorted(required - selected.keys())
        if not pending:
            if not acyclic(graph):
                return
            versions = {name: row["version"] for name, row in selected.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        rows = packages.get(name)
        if not isinstance(rows, list):
            return
        low, high = bounds[name]
        forbidden = set(blocked.get(name, []))

        options = sorted(
            (row for row in rows if valid_row(row)),
            key=lambda row: row["version"],
            reverse=True,
        )
        for row in options:
            version = row["version"]
            if version < low or version > high or version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            dependencies = []
            valid = True
            for dep in row["deps"]:
                if isinstance(dep, dict):
                    feature = dep.get("feature")
