                        if not isinstance(feature, str):
                            valid = False
                            break
                        if feature not in features:
                            continue
                spec = dependency_spec(dep)
                if spec is None:
                    valid = False
                    break
                dependencies.append(spec)
            if not valid:
                continue

            next_selected = dict(selected)
            next_selected[name] = row
            next_required = set(required)
            next_bounds = dict(bounds)
            next_graph = dict(graph)
            next_graph[name] = [dep_name for dep_name, _, _ in dependencies]
            feasible = True

            for dep_name, dep_low, dep_high in dependencies:
                next_required.add(dep_name)
                if dep_name in next_bounds:
                    old_low, old_high = next_bounds[dep_name]
                    dep_low = max(old_low, dep_low)
                    dep_high = min(old_high, dep_high)
                if dep_low > dep_high:
                    feasible = False
                    break
                next_bounds[dep_name] = (dep_low, dep_high)

                if dep_name in next_selected:
                    dep_version = next_selected[dep_name]["version"]
                    if dep_version < dep_low or dep_version > dep_high:
                        feasible = False
                        break

            if feasible:
                search(next_selected, next_required, next_bounds, next_graph)

    search({}, set(roots), initial_bounds, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
