def valid_interval(interval):
    return (
        isinstance(interval, (list, tuple))
        and len(interval) == 2
        and type(interval[0]) is int
        and type(interval[1]) is int
        and interval[0] <= interval[1]
    )


def dependency_spec(dep):
    if not isinstance(dep, dict):
        return None
    name = dep.get("name")
    low = dep.get("min")
    high = dep.get("max")
    if not isinstance(name, str) or type(low) is not int or type(high) is not int:
        return None
    if low > high:
        return None
    return name, low, high


def acyclic(graph):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dependency in graph.get(name, []):
            if not visit(dependency):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)
